  "summary": "專案成員身份驗證以讀取專案、任務列表與任務詳情",
  "acceptance_criteria": [
    "專案、任務列表、任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取",
    "非專案成員訪問回傳 403",
    "資源不存在時回傳 404"
  ]
}

{
  "summary": "專案成員身份驗證以讀取專案、任務列表與任務詳情",
  "acceptance_criteria": [
    "專案、任務列表、任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取",
